with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_NO))) as HUB_POLICY_HK
        , ELIGIBLE_DAYS as ELIGIBLE_COVERAGE_DAYS
        , PRORATA_PREMIUM as PRO_RATA_MEMBER_PREMIUM
        , ANNUAL_ER_CNTR as ANNUAL_EMPLOYER_CONTRIBUTION_AMOUNT
        , PRORATA_ER_CNTR as PRO_RATA_EMPLOYER_CONTRIBUTION_AMOUNT
        , FINAL_PAYABLE as FINAL_PAYABLE_AMOUNT
        , 'BGIL_GMC_FINAL_INSTL_DATA' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_bgil_gmc_final_instl_data') }}
    where (nullif(trim(POLICY_NO),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ELIGIBLE_COVERAGE_DAYS end) as ELIGIBLE_COVERAGE_DAYS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRO_RATA_MEMBER_PREMIUM end) as PRO_RATA_MEMBER_PREMIUM,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ANNUAL_EMPLOYER_CONTRIBUTION_AMOUNT end) as ANNUAL_EMPLOYER_CONTRIBUTION_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRO_RATA_EMPLOYER_CONTRIBUTION_AMOUNT end) as PRO_RATA_EMPLOYER_CONTRIBUTION_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then FINAL_PAYABLE_AMOUNT end) as FINAL_PAYABLE_AMOUNT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when ELIGIBLE_COVERAGE_DAYS is not null or PRO_RATA_MEMBER_PREMIUM is not null or ANNUAL_EMPLOYER_CONTRIBUTION_AMOUNT is not null or PRO_RATA_EMPLOYER_CONTRIBUTION_AMOUNT is not null or FINAL_PAYABLE_AMOUNT is not null
                     then md5(upper(coalesce(cast(ELIGIBLE_COVERAGE_DAYS as varchar), '') || '|' || coalesce(cast(PRO_RATA_MEMBER_PREMIUM as varchar), '') || '|' || coalesce(cast(ANNUAL_EMPLOYER_CONTRIBUTION_AMOUNT as varchar), '') || '|' || coalesce(cast(PRO_RATA_EMPLOYER_CONTRIBUTION_AMOUNT as varchar), '') || '|' || coalesce(cast(FINAL_PAYABLE_AMOUNT as varchar), '')))
                end as SAT_POLICY_CERTIFICATE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_CERTIFICATE_HASHDIFF is not null
